"Commander's with us!":"El comandant és amb nosaltres!",
"Oh, you're back in line!":"Ei, ja tornes a ser a la formació!",
"You lead, we follow!":"Tu mana, nosaltres et seguim!",
"Commander, slow down!":"Comandant, no tan de pressa!",
"Wait up!":"Espera'ns!",
"Congrats on the promotion!":"Felicitats per l'ascens!",
"New stripes suit you!":"Els galons nous et queden bé!",
"Pod inbound! Reinforcements!":"Càpsula d'aterratge! Arriben reforços!",
"Anyone remember why the sky is a portal?":"Algú recorda per què el cel és un portal?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Diuen que si saltes pel pou, surts al de l'enemic. No ho provaré.",
"The Swarm painted their visors red again. Show-offs.":"L'Eixam s'ha tornat a pintar els visors de vermell. Fatxendes.",
"Ore, ore… when do we get some oil?":"Mineral, mineral… i l'oli quan el repartiran?",
"I dreamt I was a toaster. It was peaceful.":"He somiat que era una torradora. Era plàcid.",
"Quiet. Too quiet.":"Silenci. Massa silenci.",
"See that? Our base is above the Swarm base again. Portals, man.":"Ho heu vist? La nostra base torna a ser damunt de la de l'Eixam. Els portals, noi.",
"Diman, if you're reading this — we need a vacation.":"Diman, si ho estàs llegint: necessitem vacances.",
