"Then click (tap) the ground: they move, stop to fight enemies they meet, then continue. On an enemy — attack it. Same as RMB.":"Després fes clic (toc) a terra: avancen, s'aturen a lluitar contra els enemics que troben i continuen. Sobre un enemic — atacar-lo. El mateix que clic dre.",
"March":"Marxa",
"Then click (tap) the ground: they run without stopping and fire on the move. Same as double RMB.":"Després fes clic (toc) a terra: corren sense aturar-se i disparen en moviment. El mateix que doble clic dre.",
"⚒ A builder builds it. No builder selected now — clicking picks the nearest idle builder and starts the blueprint.":"⚒ Construeix un enginyer. Ara no hi ha cap enginyer seleccionat: en fer clic s'escollirà el més proper lliure i s'activarà el plànol.",
