"New in v6.3":"Novetats de la v6.3",
"New in v6.2":"Novetats de la v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Nou aspecte del mineral: les vetes són cristalls esmeragda facetats i lluminosos sobre basalt negre, amb espurnes i boirina verda; l'extractor és un pedestal hexagonal amb cúpula de bresca i una torre de gelosia coronada per un far verd (franja i banderola del color de l'equip)",
"New in v6.1":"Novetats de la v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Classe preferida com a Battlefield (U, números després de morir): hi reapareixes quan està disponible",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Vehicles en primera persona (V — fora/cabina); ajuda suau de punteria: a Configuració",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Sortir del nucli és fàcil: Espai — cap al pou, B — càpsula a la superfície; els efectes de les habilitats es reinicien en morir",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Progressió sense fi: generals i Mariscal ★, nivells de carrera, mestratge d'armes i accessoris, medalles, contractes diaris: pantalla Carrera",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Estratègia: zoom suau amb la roda, icones i etiquetes sobre les unitats (Alt — totes), panell «Exèrcit / Edificis» a l'esquerra",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"Clic dre. — atacar movent-se, doble clic dre. — marxar disparant en moviment; ordres poc freqüents a «Més ordres ▾»; sense botons duplicats",
"New in v6":"Novetats de la v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Armes de tirador: bales instantànies, fusell de 720 trets/min, metralladora, retrocés, punteria amb clic dre., carregadors i recàrrega amb R, marques d'impacte",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Gravetat més pesada, jetpack més àgil, esquiva amb Z o doble jetpack a l'aire; en canviar d'unitat l'arma ja no et segueix",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Enginyers: selecciona un enginyer, tria un edifici, col·loca el plànol; extractors sobre les vetes de mineral; clica «MINERAL» per veure els ingressos i com millorar-los",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Els botons grisos expliquen el motiu i ofereixen una solució; botons més grans, franja «En curs», «▶ Controlar», Tab és l'única tecla de mode",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Càmera d'estratègia sense salts ni voltes, zoom cap al cursor, minimapa arrossegable",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Vehicles nous: assaltant «Chacal», MLRS «Grad» (coets guiats), morter «Martillo»; l'Eixam rep «Avispa», «Colmena», «Trebuchet»",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"L'estrateg manté les ordres i deixa d'omplir la ràdio; els combats venen a tu; B — redesplegament, Shift+B — al cor del combat; brúixola, H — quin objectiu",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Joc lliure (K) i actuar en solitari (J), F2 — predefinits; Esc pausa i reprèn; desades: ranures, exportació i importació",
"New in v5.3":"Novetats de la v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Vol: gravetat més forta lluny del meteorit, C a l'aire frena, l'empenta gira més ràpid; ja no et quedes encallat al portal",
"New in v5":"Novetats de la v5",
"Endless war by default and battle scale: normal, large, epic":"Guerra sense fi per defecte i escala de combats: normal, gran, èpica",
"Save and load the battle (autosave every 3 minutes)":"Desa i carrega la partida (desat automàtic cada 3 minuts)",
"Squadmates with callsigns: portraits, health and live chatter":"Companys d'esquadra amb indicatius: retrats, salut i converses en directe",
"Fog of war in strategy, friends and foes outlined differently":"Boira de guerra a l'estratègia, aliats i enemics ressaltats de manera diferent",
"Camera fly-over when switching, portal aurora instead of rings":"Sobrevol de càmera en canviar, aurora del portal en lloc d'anells",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Tasques secundàries, drecera pel cel, mòduls de la primera expedició amb provisions, cristalls, gel als cràters, tempestes de pols",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Entrenament, mode cinema amb gravació de vídeos, vehicles d'escorta de l'estrateg",
