"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Fes un toc a «Mira» — apropament. Un altre toc — enrere.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"L'esquadra et segueix. Obre ☰ → «Pausa» → la icona «Esquadra amb mi» — passarà a «Actuo sol».",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"L'enginyer està seleccionat — fes un toc a «◆ Extreure cristalls» a la seva targeta de sota (o fes un toc als cristalls verds).",
"Training complete!":"Entrenament superat!",
"steps":"passos",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Saps construir una base, encarregar tropes, comandar i saltar al combat. Ara — una partida de debò: el Curador t'ajudarà mentre jugues.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Saps moure't, volar, disparar, amagar-te i comandar l'esquadra. Ara — una partida de debò.",
"Real battle":"Combat de debò",
"Again":"Una altra vegada",
"done":"superat",
"you are on PC: keyboard and mouse":"estàs en un PC: teclat i ratolí",
"you are on a phone: touch screen":"estàs en un mòbil: pantalla tàctil",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Un camp de proves segur: els enemics són maniquins immòbils, ningú et dispara. Un pas es comptabilitza només quan tu mateix fas l'acció.",
"Show others (training for the other device)":"Mostra'n d'altres (entrenament per a l'altre dispositiu)",
"Old training (v7.1)":"Entrenament antic (v7.1)",
"Back to the normal device mode":"Tornar al mode normal del dispositiu",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"L'entrenament per a l'altre dispositiu reiniciarà la pàgina en el seu mode (PC — ratolí i teclat, mòbil — tàctil; en un PC pots provar el tàctil a Chrome: F12 → icona del mòbil).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Entrenament ×4: lliçons separades pas a pas d'«Estratègia» i de «Tirador» per a PC i per a mòbil. Un camp de proves segur amb maniquins, el botó correcte ressaltat, fletxes, tecles, ratolí i gestos animats; un pas només compta amb l'acció real, «repetir el pas», progrés a dalt i una recompensa al final",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"El menú Entrenament mostra les lliçons del teu dispositiu; «Mostra'n d'altres» — les quatre en qualsevol dispositiu; l'«Entrenament antic (v7.1)» continua allà",
"New in v7.2":"Novetats de la v7.2",
"NEW IN v7.2":"NOVETATS DE LA v7.2",
"No grenades left":"No queden granades",
"Rocket and grenade recharging · {0} s":"Recàrrega de coet i granada · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Esquerra — moure't, dreta — mirar · toc a un enemic — coet / granada · 2 tocs — reflex · 3 tocs — atac d'artilleria",
"Less":"Menys",
"More":"Més",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Vehicle o estructura enemiga a prop — toca-la: sortirà un coet.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Molts hostils — toca dues vegades un espai buit a la dreta: el reflex alentirà el temps.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Apunta al grup d'enemics i toca 3 vegades — atac d'artilleria.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Dit esquerre — moure't, dit dret — mirar. Dispara sol quan apuntes a un enemic.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ a la vora esquerra — jetpack: toca per saltar, mantén per volar.",
"Old v7.2 layout":"Disposició antiga de la v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Arrossega un dit per la meitat dreta de la pantalla — sota el dit apareixerà una palanca de visió.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Toca el costat esquerre i llisca — apareixerà una palanca sota el dit. Arriba al marcador verd.",
"Hold the \"Jet\" button at the left edge.":"Mantén el botó «Jet» a la vora esquerra.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Amb la palanca dreta apunta a un maniquí — el soldat dispara sol quan la mira és sobre l'objectiu.",
"Tap the dummy on the screen — a rocket flies.":"Toca el maniquí a la pantalla — sortirà un coet.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Toca el maniquí — sortirà una granada en arc, directa cap a ell.",
"Double tap an empty spot on the right quickly.":"Toca ràpidament dues vegades un espai buit a la dreta.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Mode lleuger per a mòbils febles: resolució més baixa, sense ombres ni distorsió, la meitat de bots i partícules, límit de 30 FPS; baixa la resolució sol si els FPS < 25. Activat per defecte als mòbils (Configuració → Gràfics → «Mode lleuger»; o ?lite=1 / ?lite=0 a l'enllaç).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Mòbil: controls nous. Esquerra — moure't, dreta — mirar (les dues palanques apareixen sota el dit). Només el dit esquerre — «auto»; quan fas servir el dret, el soldat dispara sol només mentre la mira és sobre un enemic. Toc a un enemic — coet o granada, 2 tocs — reflex, 3 tocs — atac d'artilleria. Recàrrega automàtica. Jetpack — un botó a la vora esquerra. Les cantonades inferiors són lliures, minimapa a la cantonada, les pistes es poden tancar amb una creu, l'objectiu es pot plegar. Disposició antiga: Configuració → Mòbil.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Pistes (finestres emergents i Curador) — un sol interruptor a la configuració. Qui ets (tipus de soldat o de vehicle) — etiqueta «Tu: …» al HUD. Les òptiques del fusell i de la metralladora són transparents. El tauler «Arsenal» està acoblat a la dreta, es pot plegar i desactivar. S'ha eliminat el mode «sol sense esquadra» (J). L'estratega IA ja no repeteix la mateixa frase. Els tancs tenen un indicador de torreta respecte al casc. El cursor ja no desapareix a l'inici de l'entrenament d'estratègia.",
