"Voice of hints & curator":"Veu de pistes i Curador",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Mòbil: tres modes de palanca. Només l'esquerra — «auto» (imant fort, bales més febles). Només la dreta — la punteria s'activa sola, imant més fort, millor precisió. Totes dues — sense punteria, imant i precisió més febles. El botó 👁 de la dreta amaga/torna el HUD.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Mòbil: estratègia simplificada — només enginyer i edificis. Targetes a l'esquerra (enginyer, QG, Caserna…): toc — la càmera hi vola, la barra inferior mostra què construir/produir. «Al combat» — a dalt a l'esquerra. L'exèrcit lluita sol. Estratègia completa — Configuració → Mòbil.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Possessió — dues opcions: «Esquadres» i «Vehicles» (als mòbils els vehicles estan desactivats per defecte — els condueix la IA). Amb els vehicles desactivats, E (mòbil: el botó de la dreta) al costat d'un vehicle aliat — controla'n el canó: ell va sol, tu dispares. L'antic «ordre de classes propi» és a «Avançades». Una unitat respon per ràdio quan la controles.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Pistes intel·ligents: les pistes bàsiques s'apaguen soles després del 2n inici, però el joc t'assenyalarà una funció que no facis servir mai. Opcions: bàsiques / avançades / rares, i una de separada per a la veu de les pistes i del Curador.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"El reflex es carrega amb les baixes (les ratxes carreguen més). Els companys s'han endarrerit o han mort — l'estrateg te'n deixa de nous (més car que el reforç normal). S'han integrat els gràfics i el so de la v7.2gfx: explosions en núvols, fum, runa, acústica de pous i cràters. La data de la compilació ja és real.",
