"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"La Carrera i les partides desades no canvien. En combat, el mateix menú és el botó «🛠 Menú» a dalt a la dreta{0}.",
"New developer match":"Partida nova de desenvolupador",
"all unlocked, endless ore, instant build, arsenal":"tot desbloquejat, mineral il·limitat, construcció instantània, arsenal",
"Trainings — all 4":"Entrenaments — els 4",
