"strategist bot left, shooter bot right":"bot estrateg a l'esquerra, bot tirador a la dreta",
"Cinema: everything built":"Cinema: tot construït",
"both bases built and upgraded — for footage":"totes dues bases construïdes i millorades — per a enregistrar",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Mode cinema — pantalla dividida: a l'esquerra el bot estrateg (vista aèria de la base i l'exèrcit), a la dreta el bot tirador en primera persona. Botons a baix (tecles S, P): «Pantalla dividida» i «★ Tot construït» — totes dues bases construïdes i millorades per a enregistrar.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"El nucli i els túnels a través del meteorit ja no hi són — el meteorit és massís, el combat és només a la superfície.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Mòbil: 👁 amaga la interfície però deixa el jetpack, ⇆, les palanques i el marcador d'objectiu. «◎ Punteria» (només el dit dret) — un imant clarament més fort i més ample; la força de l'imant per als tres modes — Configuració → Controls → «Avançat». A la torreta d'un vehicle, el botó es diu «Baixar».",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Entrenament: al telèfon només els de telèfon, al PC només els de PC. Els 4 són al menú «🛠 Desenvolupador». El mode desenvolupador i l'Arsenal ara són un sol menú (en combat — «🛠 Menú» a dalt a la dreta, F8 al PC).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Estils gràfics «Dendy (8 bits)» i «16 bits»: Configuració → Gràfics → «Estil gràfic» (detalls — el botó ⚙). Si els FPS són inferiors a 24 durant els primers ~10 s d'una partida, Dendy s'activa sol (per sota de 20 — píxels més grans, 120 línies); l'avís «tornar a la normalitat» restaura els gràfics normals per sempre. La teva elecció al menú sempre preval.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"Models 3D de l'entorn (ruïnes, restes, fortificacions) — només els ben valorats, es carreguen a demanda. Desactivar: Configuració → Gràfics → «Nous models 3D de l'entorn».",
