"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Els soldats poden construir: E (al telèfon «Entrar») en una obra pròpia — el teu soldat construeix, els companys d'esquadra propers l'ajuden. Si els enginyers estan ocupats, l'estrateg et demana ajuda — marcador «OBRA D'EDIFICI».",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Marques de l'estrateg: l'estrateg posa ⌖ sobre un grup d'enemics a prop teu — l'artilleria hi colpeja 8 s després i els MLRS \"Grad\" aliats propers fan una salva. El teu propi atac d'artilleria des del mode estratègia també té suport dels \"Grad\".",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Amagatalls d'armes en contenidors de càrrega i satèl·lits estavellats (📦 visible des de 70 m): E — una metralladora pesant durant 90 s, munició incendiària o coets, a més de granades plenes. Arrossegar-se: Ctrl — estendre's / aixecar-se (més baix, més estable la punteria, però lent).",
