"Camera shake":"Tremolor de càmera",
"Slow-mo on major kills":"Càmera lenta en baixes importants",
"\"What to do now\" hint":"Pista «què cal fer ara»",
"from blasts and hits, gentle":"per explosions i impactes, suau",
"last enemy nearby, tank, HQ":"últim enemic a prop, tanc, QG",
"corner; F7 — collapse":"a la cantonada; F7 — plegar",
"Link copied":"Enllaç copiat",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"«▶ Jugar ara» — el primer botó del menú: un vol curt sota el cel portal i directe al combat (ometre amb qualsevol tecla o un toc).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Els impactes es noten: so metàl·lic i guspires, una marca de baixa al punt de mira (al cap — groga), una ratxa ×N, tremolor suau per les explosions, càmera lenta en les baixes clau. El tremolor, la càmera lenta i la pista es poden desactivar a Configuració.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Resultats de la partida: temps, baixes, millor ratxa, ★ MVP i millor esquadra, una targeta de partida — «⇪ Compartir», PNG o enllaç al joc.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Una pista «què cal fer ara» a l'esquerra sota els recursos: l'ordre de l'estrateg, un punt per capturar, un atac de l'Eixam. ✕ o F7 — plegar.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"El combat es desa sol si tanques o amagues la pestanya — «⟲ Continuar» al menú.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"La v7.5 es manté al menú «🕘 Versió del joc» per si la prefereixes. Ara s'envien estadístiques anònimes (sense noms ni correu); es poden desactivar a Configuració.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"«Jugar ara», resposta dels impactes, resultats de partida amb targeta, pista «què cal fer», desat automàtic",
"and older: v7.5, v7.4, milestones v1–v7.0":"i anteriors: v7.5, v7.4, fites v1–v7.0",
"New in v7.6":"Novetats de la v7.6",
"NEW IN v7.6":"NOVETATS DE LA v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Tria la teva facció abans d'una partida: el «Consorci» (infanteria pesant amb armadura assistida, blindatge i artilleria) o l'«Eixam» (velocitat, estols de drons, trets pesants amb distorsió). La IA juga amb l'altra. L'elecció es recorda.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Cada facció té els seus vehicles i exclusius: el Consorci — el tanc \"Rinoceront\" i les «Plaques de ceramita», l'Eixam — l'«Estol de drons» i els «Jetpacks de fase». Equilibri comprovat amb partides de bots.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Cràters d'explosió: l'artilleria, els coets i els canons dels tancs obren sots al meteorit — s'hi pot caminar i conduir, i et pots amagar a dins.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Vista en tercera persona per al soldat (V, es recorda; al mòbil — Controls) i una càmera suau per als vehicles amb una marca d'on impactarà el canó.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"La v7.6 continua al menú «🕘 Versió del joc» per si la prefereixes.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Faccions Consorci / Eixam amb elecció abans de la partida, cràters d'explosió, vista en tercera persona",
"and older: v7.6, v7.5, milestones v1–v7.0":"i anteriors: v7.6, v7.5, fites v1–v7.0",
