"Anomaly ahead! The vein is singing — go around!":"Anomalia al davant! La veta canta — la rodegem!",
"Hear that hum? A singing vein. Keep clear!":"Sentiu aquest brogit? És una Veta Cantora. No us hi acosteu!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomalia! L'aire gira — és un remolí, rodeja'l!",
"Rocks floating in the air… A whirlpool! Stay out!":"Roques flotant a l'aire… Un remolí! No hi entris!",
"Anomaly ahead — it is crackling with current!":"Anomalia al davant — espetega de corrent!",
"Rods and lightning — a Crackler. It loves armour!":"Pues i llamps — un Cruixidor. Li encanta el blindatge!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomalia! El terra tremola de calor — un Braser!",
"Careful, a Brazier underfoot!":"Compte, un Braser sota els peus!",
"Anomaly — green mist! Acid, hold your breath!":"Anomalia — boira verda! Àcid, aguanteu la respiració!",
"The mist is drifting our way, go around!":"La boira s'arrossega cap a nosaltres, rodegem-la!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomalia! L'aire és com un vidre — una Lent, doblega les bales!",
"Everything is warping… a Lens nearby!":"Tot es deforma… una Lent a prop!",
"Ha! An enemy walked right into the anomaly!":"Ha! Un enemic ha entrat de ple en l'anomalia!",
"Got him! Lure them into anomalies!":"Atrapat! Atrau-los cap a les anomalies!",
"Beautiful zap! One less tin can.":"Quin espetec més bonic! Una llauna menys.",
