"They say veins hide artifacts. Only first the vein sings…":"Diuen que a les vetes s'hi amaguen artefactes. Només que abans la veta canta…",
"Throw a bolt first, then walk. Old habit.":"Llança un cargol primer, i després camina. Vell costum.",
