" — close":" — tancar",
"Supply drop":"Caixa de subministrament",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Llança una caixa prop de les teves forces: munició, granades, coets, peces d'arma, un kit de reparació.",
"\"Grad\" rocket strike":"Atac de coets \"Grad\"",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 coets sobre una àrea àmplia al cap de 3 segons — més ràpid i ample que un atac d'artilleria.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Suport: caixa, exploració, \"Grad\", atac d'artilleria (després 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"ATENCIÓ: \"Grad\" de l'Eixam sobre la teva zona!",
"Warning! Rocket salvo on our position!":"Atenció! Salva de coets sobre la nostra posició!",
"take the supply crate":"agafar la caixa de subministrament",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomalies al meteorit (onada 1): la «Veta Cantora» — un cristall verd lluminós que brunz i colpeja amb pulsos rítmics tothom qui és a prop; el «Remolí» estira i llança, el «Cruixidor» llança arcs entre les pues, el «Braser» s'encén sota els peus, la «Boira àcida» i la «Lent» (doblega les bales i la imatge) van a la deriva.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Les anomalies es noten abans d'hora (brunzit, resplendor, calitja). Descarrega-les amb una granada, un coet o un pern (E a prop seu): s'adormiran i de vegades deixaran un artefacte amb un pro i un contra. L'esquadra avisa per ràdio, i els enemics (i els aliats) de vegades hi entren — atrau-los!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Suport amb punts de comandament: 4 en combat (📡 al mòbil) — caixa de subministrament, exploració, atac de \"Grad\", artilleria al punt de mira. L'estrateg només veu les anomalies al mapa després d'una exploració.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Caixes de subministrament a les ruïnes d'antigues expedicions, prop dels QG i al costat dels edificis acabats: munició, granades, coets, peces d'arma (desbloquegen accessoris).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"La v7.7 continua al menú «🕘 Versió del joc». Les anomalies es poden desactivar a Configuració.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomalies (la «Veta Cantora» i 5 més), descàrrega amb pern i granada, artefactes, suport per PM, caixes de subministrament",
"and older: v7.7, v7.6, milestones v1–v7.0":"i anteriors: v7.7, v7.6, fites v1–v7.0",
"New in v7.8":"Novetats de la v7.8",
"NEW IN v7.8":"NOVETATS DE LA v7.8",
"Close":"Tancar",
"Anomalies on the meteor":"Anomalies al meteorit",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ a la cantonada obre el menú de pausa: Continuar, Tornar a començar, Entrenament, Gràfics, Configuració, Menú principal (amb confirmació). Mòbil: ☰ a dalt a la dreta (accions de combat — la casella «⚡ Accions»); PC: el botó «☰ Menú» a dalt a la dreta o Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Els gràfics sempre són normals per defecte — Dendy només si el trieu: l'interruptor «Gràfics: Normal / Dendy (8 bits) / 16 bits» és al menú principal i al de pausa. Si el joc va molt lent, apareix un consell amb el botó «Activar Dendy».",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Mòbil i tauleta: el botó d'acció «✋» de la dreta només apareix quan hi ha alguna cosa a fer a prop — «Agafar» (amagatall, caixa), «Pujar» (vehicle, torreta, canó), «Construir», «Baixar», «Pern» en una anomalia. També pots tocar l'objecte il·luminat.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Mòbil, estratègia: mantén el dit ~0,3 s (el mòbil vibra, apareix un anell groc) i arrossega — marc de selecció; un lliscament normal mou la càmera. També hi ha el botó «Marc» a la dreta; a l'entrenament el pas «Marc» també accepta tocar una esquadra.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Mòbil: els botons petits són més fàcils de prémer, la llista de suport 📡 és més gran, els panells d'estratègia ja no tapen la pausa ni els resultats. La v7.8 continua al menú «🕘 Versió del joc».",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Menú ☰ al mòbil i al PC, sense Dendy automàtic, botó «✋» en tàctil, selecció amb marc al mòbil",
"16-bit":"16 bits",
"Lagging? Try the Dendy graphics — they are lighter.":"Va lent? Prova els gràfics Dendy — són més lleugers.",
"Turn on Dendy":"Activar Dendy",
"Use":"Acció",
"Man gun":"Al canó",
"Board":"Pujar",
"Man it":"Seure-hi",
"Take":"Agafar",
