"NEW IN v7.8.1":"NOVETATS DE LA v7.8.1",
"Restart?":"Tornar a començar?",
"Quit to the main menu?":"Sortir al menú principal?",
"The training starts from step one.":"L'entrenament començarà des del primer pas.",
"The current battle ends and a new match starts with the same settings.":"El combat actual acabarà i començarà una partida nova amb la mateixa configuració.",
"Yes, restart":"Sí, tornar a començar",
"Yes, quit":"Sí, sortir",
"No, go back":"No, tornar enrere",
"Battle actions":"Accions de combat",
"dash, redeploy…":"Embranzida, redesplegament…",
"Restart":"Tornar a començar",
"Shooter":"Tirador",
"The Commander mode is not in the game yet":"El mode Comandant encara no és al joc",
"Commander · soon":"Comandant · aviat",
"Commander — still in development":"Comandant — encara en desenvolupament",
"Pause: resume, restart, training, graphics, settings, main menu":"Pausa: continuar, tornar a començar, entrenament, gràfics, configuració, menú principal",
"Menu: pause, restart, training, graphics, settings":"Menú: pausa, tornar a començar, entrenament, gràfics, configuració",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Mantén el dit a terra ~0,3 s — el mòbil vibra i apareix un anell groc — i, sense deixar anar, arrossega: es forma un marc. O el botó «Marc» de la dreta. També val tocar una esquadra.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Per a pantalla completa a l'iPhone: «Comparteix» ⬆ → «Afegeix a la pantalla d'inici» — el joc s'obrirà sense les barres de Safari.",
"Open portal-meteor.pages.dev for that.":"Per a això, obre portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Toc — seleccionar · toc a terra — moure's · mantén — menú d'ordres · mantén i arrossega — marc · 2 dits — zoom",
"Robo-ninja":"Robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Heroïna assassina: embranzides teletransportades, katana, shurikens. Salta per les zones enemigues pel seu compte i talla robots a trossos. 1 per bàndol.",
"Shadow protocol":"Protocol «Ombra»",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Investigació: desbloqueja la robo-ninja a la Caserna. Cal una fàbrica de mecs acabada.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Heroïna (1 per bàndol): es teletransporta per les zones enemigues pel seu compte i esquarta robots; la pots controlar per jugar manualment.",
"is ready. She works on her own (AUTO) — possess her to play manually":"és a punt. Treballa sola (AUTO) — controla-la per jugar manualment",
"Robo-ninja ready for action":"Robo-ninja a punt per al combat",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Exploració: l'enemic té una robo-ninja!",
"Warning! The enemy has a robo-ninja. Stay together":"Atenció! L'enemic té una robo-ninja. Mantingueu-vos junts",
"cyber blinks":"embranzides cibernètiques",
"Too far for a dash — get closer or teleport":"Massa lluny per a l'embranzida — acosta't o teletransporta't",
"point ":"punt ",
