"order":"ordre",
"nearby":"a prop",
"Zone cleared":"Zona neta",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ DUEL DE NINJES! Bloqueja just abans d'un cop per parar-lo, embranzida per esquivar. Atent al llampec de la preparació",
"The two ninjas have met in a duel!":"Les dues ninges s'han enfrontat en un duel!",
"⚔ Duel won! Our ninja prevails":"⚔ Duel guanyat! La nostra ninja s'imposa",
"⚔ Duel lost…":"⚔ Duel perdut…",
"ninja duel":"duel de ninges",
"POSTURE BROKEN":"POSTURA TRENCADA",
"Teleport":"Teletransport",
"Teleport: aim at the ground (up to 150 m)":"Teletransport: apunta a terra (fins a 150 m)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: salta per les zones enemigues i talla pel seu compte. Joystick / WASD — pausa d'1,5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Manual: toc a un enemic — embranzida i tall, lliscament — cop, 🛡 — bloqueig",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Manual: clic esq. — katana, clic dre. — bloqueig, Shift — embranzida, Q — shurikens, G — teletransport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: toc a un enemic — embranzida i tall, lliscament a la dreta — cop, ● — atac, 🛡 — bloqueig (a temps = parada), ⇑ — avanç, ✦ — shurikens, ◎ — teleport, AUTO — per compte seu",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: clic esq. — katana (mantén — tall pesat), clic dre. — bloqueig (a temps = parada), Shift/Z — avanç, Q — shurikens, G — teleport a la mira, salt a l'aire — doble salt / cursa per la paret, {0} — AUTO",
