"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Ràdio Portal Meteor: més de 100 temes d'EDMITRY dins del joc — botó 📻 (PC: tecla 5, [ ] — tema). La música es carrega en línia i no engreixa el joc; volum i inici automàtic a Configuració, i enllaç «Escolta a Spotify».",
