"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 a la dreta — Ràdio Portal Meteor: música d'EDMITRY mentre lluites.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Ràdio Portal Meteor: música d'EDMITRY mentre lluites. [ ] — tema.",
"Radio Portal Meteor (EDMITRY): volume":"Ràdio Portal Meteor (EDMITRY): volum",
"Radio: start by itself in battle":"Ràdio: activar-se sola en combat",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: una cíborg amb katana. Es desbloqueja a la Caserna amb la investigació «Protocol Ombra» (cal una Fàbrica de mecs). Es teletransporta sola a les zones enemigues, talla els enemics a trossos (sense sang — guspires), avanços, shurikens, duels amb el ninja enemic. Controla-la — mode AUTO o control manual (al mòbil, botons propis).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Ràdio Portal Meteor: 103 temes d'EDMITRY dins del joc. Tecla 5 (reassignable); al mòbil — ☰ → Configuració → So. Volum i «activar-se sola en combat» a la configuració; la música baixa amb les explosions i amb la veu de la ràdio.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Idiomes nous: uzbek i tadjik — complets; xinès, castellà, portuguès — parcials. Nou selector d'idioma al menú, al costat de «Partida nova».",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Mòbil: «amagar icones» 👁 recull els botons restants en una columna ordenada a la vora dreta; el mode vertical ja no se solapa; iPhone — el joc ja no es barallia amb els gestos de Safari, i «Comparteix → Afegeix a la pantalla d'inici» l'obre a pantalla completa.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"De la v7.8.1: menú ☰ a la cantonada (pausa, reiniciar, entrenament, gràfics), sense Dendy automàtic, botó d'acció ✋ al mòbil. La v7.8.1 i la v7.8 queden al menú «🕘 Versió del joc».",
