"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"Una zona de foc de 12 m crema durant 9 segons: dany continuat, supressió, fum. Al cap de 2.5 s. Encén el metà.",
