"Walker \"Reaper\"":"Camina-mec «Segador»",
"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"Eixam. Cap: 12500 de blindatge, feix de distorsió, trepitjada. Passa per sobre de les barreres. Punt feble — el nucli sota la panxa. Un per exèrcit.",
