"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Eixam. Les esquadres a menys de 70 m del cau (i les seleccionades), i els vehicles lleugers/mitjans seleccionats («Chacal», «Martell», «Grad»), passen pel túnel. O bé: selecciona i clic dre./toc al cau.",
