"Living world: your units ask for help, heroes give quests. Card on the right — ✕ to dismiss.":"Món viu: els teus demanen ajuda, els herois donen missions. Targeta a la dreta — ✕ per descartar.",
"Living world: your units ask for help, heroes give quests. Y — accept, N — decline.":"Món viu: els teus demanen ajuda, els herois donen missions. Y — acceptar, N — rebutjar.",
