"Living world: requests, hero quests, breakthrough ops":"Món viu: peticions, missions d'herois, operacions de gir",
"Living world":"Món viu",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Els teus demanen ajuda i et recompensen, els herois donen missions, un front encallat es trenca amb una operació de ruptura",
"A request":"Una petició",
"Breakthrough":"Ruptura",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"De vegades els teus demanen ajuda: veu per ràdio, targeta «PETICIÓ» i marcador ✋. Una esquadra està immobilitzada — destrueix els enemics que té a prop. Recompensa: un soldat per càpsula des de la base, una arma del maleter d'un bagui, el lloc de tirador o cobertura orbital. Ara no? — ✕ o ignora-ho.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"L'explorador veterà «Mussol» ofereix una missió. Y — acceptar (N — rebutjar). Ves a la marca ★, elimina els guàrdies i queda't 3 s vora el pilot — s'unirà a la teva esquadra.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"El front s'ha encallat — el QG ofereix una ruptura. Y — acceptar. Domina el relé 8 s sense enemics a prop: el mapa enemic serà visible 60 s. El generador — les torretes enemigues callen 2 min. A Estratega — «Assignar a una esquadra». L'enemic també ho sap fer: vigila el ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Els teus demanen ajuda: targeta «PETICIÓ» i marcador ✋. Destrueix els enemics prop de l'esquadra immobilitzada — rebràs una recompensa. ✕ — ometre.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"L'heroi «Mussol» ofereix una missió — toca «Acceptar». Ves a ★, elimina els guàrdies, queda't vora el pilot.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"El front s'ha encallat — toca «Acceptar» i domina el relé 8 s: el mapa enemic s'obrirà durant un minut.",
"Pod redeploy from the base: {0} m — through the sky portal":"Trasllat per càpsula des de la base: {0} m — pel portal celeste",
"Pod away from the base! Hold on — exit over the target.":"La càpsula ha sortit de la base! Aguanteu — sortida sobre l'objectiu.",
"Landed at the objective!":"Descens a l'objectiu!",
"LAUNCH FROM BASE":"LLANÇAMENT DES DE LA BASE",
"LANDING":"ATERRATGE",
"REDEPLOY":"TRASLLAT",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"El borrissol d'acer s'ha enganxat — corroeix el blindatge −2/s. Queda't quiet 3 s o troba un enginyer",
"An engineer brushed the fluff off":"Un enginyer t'ha netejat el borrissol",
