"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. Juga i pensa en veu alta: què no s'entén, què molesta, què diverteix. A la cantonada es veuen versió, hora i FPS: serveixen per fer coincidir la gravació amb les notes.",
