"you lead one squad":"dirigeixes una esquadra",
"you command the whole army from above":"comandes tot l'exèrcit des de dalt",
"Want to command the army?":"Vols comandar l'exèrcit?",
"Unlock the Strategist mode: look from above and give orders to the whole army.":"Desbloqueja el mode Estratega: mires des de dalt i dones ordres a tot l'exèrcit.",
"Want to lead one squad?":"Vols dirigir una esquadra?",
"Unlock the Commander mode: camera over a squad, tap where to go.":"Desbloqueja el mode Comandant: la càmera damunt d'una esquadra, toca on ha d'anar.",
"Yes":"Sí",
"Later":"Més tard",
"You run and shoot yourself. That is how you have played so far.":"Corres i dispares tu mateix. Així has jugat fins ara.",
"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"Mires des de dalt i comandes tot l'exèrcit: construeixes la base, envies esquadres. L'exèrcit també lluita pel seu compte.",
"You lead one squad: the camera is above it, tap the ground to move.":"Dirigeixes una esquadra: la càmera és damunt seu, toca el terra per moure't.",
"The mode button is at the top right: tap for the next mode.":"El botó de mode és a dalt a la dreta: toc — mode següent.",
