"Hint hidden — tap «?» to open it. To leave the lesson: ☰ → «Leave lesson»":"Pista amagada — toca «?» per obrir-la de nou. Per sortir de la lliçó: ☰ → «Sortir de la lliçó»",
"◎ precise":"◎ precís",
"○ running":"○ correr",
"◉ run + aim":"◉ correr + apuntar",
"Commander mode, faction bosses, living meteor (terrain, biomes, weather, anomalies, fauna), living world; faster, gamepad, tablet, encyclopedia, feedback mode, simple phone interface":"Mode Comandant, caps de facció, meteorit viu (relleu, biomes, clima, anomalies, fauna), món viu; més ràpid, comandament, tauleta, enciclopèdia, mode Opinió, interfície simple per al mòbil",
"Three modes on one button: Shooter (you fight yourself), the new Commander (lead one squad, 4 abilities per unit type) and Strategist. On the phone — a simple interface: fewer buttons, modes unlock during the battle.":"Tres modes en un sol botó: Tirador (lluites tu mateix), el nou Comandant (dirigeixes una esquadra, 4 habilitats per tipus d'unitat) i Estratega. Al mòbil — una interfície simple: menys botons, els modes es desbloquegen durant el combat.",
"Living meteor: rocks, ridges, a hangar in a mesa, lava / ice / methane lakes, three biomes, local weather, new anomalies and native fauna.":"Meteorit viu: roques, crestes, un hangar en una mesa, llacs de lava, gel i metà, tres biomes, clima local, noves anomalies i fauna autòctona.",
"Factions play differently: the Swarm digs tunnels and regenerates, the Consortium builds barriers and repairs. From minute 12 — the Bastion and Reaper bosses; you can possess your own.":"Les faccions ara són diferents: l'Eixam excava túnels i es regenera, el Consorci posa barreres i repara la tecnologia. Des del minut 12 — els caps «Bastió» i «Segador»; pots controlar el teu.",
"Living world: your troopers ask for help over the radio (with a reward), heroes give quests, a stalled front gets a \"Breakthrough\" operation. Capsules, crates and strikes launch from the base through the sky portal.":"Món viu: els teus soldats demanen ajuda per ràdio (amb recompensa), els herois donen missions, quan el front s'encalla arriba l'operació «Canvi de rumb». Càpsules, caixes i atacs surten de la base a través del portal celeste.",
"Faster (a frame up to 2x cheaper), gamepad in every mode, tablet layout, an encyclopedia of everything in the game, feedback mode — a note with a screenshot on one key.":"Més ràpid (un fotograma fins a 2 vegades més barat), comandament en tots els modes, disposició per a tauleta, una enciclopèdia de tot el joc, mode Opinió — una nota amb captura amb una sola tecla.",
"All new texts are translated into Uzbek, Tajik, Chinese, Spanish, Portuguese and Hebrew. The v7.9 ninja and radio stay; v7.9 is in the \"🕘 Game version\" menu.":"Tots els textos nous estan traduïts a l'uzbek, tadjik, xinès, castellà, portuguès i hebreu. El ninja i la ràdio de la v7.9 hi són; la v7.9 és al menú «🕘 Versió del joc».",
